<?php
$suiteModule='receipts';require __DIR__.'/../common.php';if(!isset($suiteWorkspace))return;
$receipt=null;$key=is_string($_GET['key']??null)?$_GET['key']:'';
if($key!==''){$s=$conn->prepare('SELECT r.*,u.username,l.name AS location FROM erp_pos_checkouts r LEFT JOIN users u ON u.id=r.cashier_id JOIN erp_locations l ON l.id=r.location_id WHERE request_key=?');$s->execute([$key]);$receipt=$s->get_result()->fetch_assoc();if(!$receipt){http_response_code(404);echo '<p class="alert alert-warning">Receipt not found.</p>';}}
?>
<div class="suite-heading mb-3 suite-no-print"><h4 class="m-0">POS Receipts</h4><div class="suite-actions"><a href="<?php echo base_url ?>admin/?page=pos" class="btn btn-primary btn-sm"><i class="fas fa-cash-register mr-1"></i> POS</a><?php if($receipt): ?><button class="btn btn-outline-secondary btn-sm suite-print" type="button" title="Print receipt" aria-label="Print receipt"><i class="fas fa-print"></i></button><?php endif ?></div></div>
<?php if($receipt): $details=json_decode($receipt['details'],true);$response=json_decode($receipt['response'],true); ?>
<section class="suite-receipt"><h4><?php echo $suiteEscape($_settings->info('name')) ?></h4><p><?php echo $suiteEscape($receipt['location']) ?></p><h6>POS-<?php echo str_pad($receipt['id'],8,'0',STR_PAD_LEFT) ?></h6><p class="small"><?php echo $receipt['created_at'].' | '.$suiteEscape($receipt['username']??'') ?></p><?php $rows=[];foreach($details['items'] as $line)$rows[]=['Item'=>$line['name'],'Quantity'=>$line['entered_quantity'],'Unit'=>$line['unit_name'],'Price'=>$line['entered_price'],'Amount'=>$line['amount']];$suiteTable($rows); ?><dl class="po-totals"><dt>Total (NPR)</dt><dd><?php echo $receipt['amount'] ?></dd><dt>Tendered</dt><dd><?php echo $suiteEscape($details['tendered']) ?></dd><dt>Change</dt><dd><?php echo $suiteEscape($response['change_due']) ?></dd></dl></section>
<?php else:$records=$conn->query('SELECT r.*,u.username,l.name AS location FROM erp_pos_checkouts r LEFT JOIN users u ON u.id=r.cashier_id JOIN erp_locations l ON l.id=r.location_id ORDER BY r.id DESC LIMIT 250')->fetch_all(MYSQLI_ASSOC); ?>
<div class="table-responsive"><table class="table table-sm table-striped"><thead><tr><th>Receipt</th><th>Date / Time</th><th>Location</th><th>Cashier</th><th class="text-right">Amount (NPR)</th></tr></thead><tbody><?php foreach($records as $row): ?><tr><td><a href="<?php echo $suiteEscape($suiteUrl) ?>&key=<?php echo $suiteEscape($row['request_key']) ?>">POS-<?php echo str_pad($row['id'],8,'0',STR_PAD_LEFT) ?></a></td><td><?php echo $row['created_at'] ?></td><td><?php echo $suiteEscape($row['location']) ?></td><td><?php echo $suiteEscape($row['username']??'') ?></td><td class="text-right"><?php echo $row['amount'] ?></td></tr><?php endforeach ?></tbody></table></div>
<?php endif ?></div>
